class BilliardBallRotation extends StatefulWidget {
  @override
  _BilliardBallRotationState createState() => _BilliardBallRotationState();
}

class _BilliardBallRotationState extends State<BilliardBallRotation> {
  Object ball;
  double angle;
  Vector3 axis;

  @override
  void initState() {
    super.initState();
    ball = Object(fileName: 'assets/ball.obj');
    angle = pi / 4; // 45 degrees
    axis = Vector3(0, 1, 0); // Rotating around y-axis
  }

  void updateBallRotation(double force) {
    // Calculate rotation angle based on force
    double rotationAngle = force * angle;

    // Create rotation quaternion
    Quaternion rotation = Quaternion.axisAngle(axis, rotationAngle);

    // Apply rotation to ball
    ball.rotation.setFrom(rotation);

    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Billiard Ball Rotation'),
      ),
      body: Container(
        child: Cube(
          onSceneCreated: (Scene scene) {
            scene.world.add(ball);
            scene.camera.zoom = 10;
          },
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () {
          updateBallRotation(1.0); // Testing with force value of 1.0
        },
        child: Icon(Icons.rotate_right),
      ),
    );
