    ball.rotation.applyQuaternion(newOrientation);

    for (var rect in rectangles) {
      // Verificar colisão com o retângulo
      if (ball.position.x + radius > rect.x &&
          ball.position.x - radius < rect.x + rect.width &&
          ball.position.y + radius > rect.y &&
          ball.position.y - radius < rect.y + rect.height) {
        // Calcular o ponto mais próximo no retângulo
        double nearestX =
            max(rect.x, min(ball.position.x, rect.x + rect.width));
        double nearestY =
            max(rect.y, min(ball.position.y, rect.y + rect.height));

        // Calcular a distância do ponto mais próximo até o centro da bola
        double deltaX = ball.position.x - nearestX;
        double deltaY = ball.position.y - nearestY;
        double distance = sqrt(deltaX * deltaX + deltaY * deltaY);

        if (distance < radius) {
          // Ajustar a posição da bola para fora do retângulo
          double overlap = radius - distance;
          ball.position.x += (deltaX / distance) * overlap;
          ball.position.y += (deltaY / distance) * overlap;

          // Inverter a velocidade para simular o rebote
          if (deltaX.abs() > deltaY.abs()) {
            velocityX = -velocityX * CUSHION_RESTITUTION;
          } else {
            velocityY = -velocityY * CUSHION_RESTITUTION;
          }
        }
      }
    }

    ball.updateTransform();
  }
}

class Rectangle {
  double x, y, width, height;

  Rectangle(this.x, this.y, this.width, this.height);

  bool contains(double px, double py) {
    // Verifica se o ponto (px, py) está dentro do retângulo
    return px > x && px < x + width && py > y && py < y + height;
  }
}

